    "objective": "oep-ke-keph-pharmacy-068",
    "course": "paper-2",
    "topic": "Stage 1 · Clinical Pharmacy",
    "prompt": "Which statement about generic substitution is correct?",
    "options": [
      [
        "oep-ke-keph-pharmacy-068-option-0",
        "A generic medicine has a different active ingredient from the originator"
      ],
      [
        "oep-ke-keph-pharmacy-068-option-1",
        "A generic medicine contains the same active ingredient and must meet bioequivalence and quality standards"
      ],
      [
        "oep-ke-keph-pharmacy-068-option-2",
        "Generic medicines are always less effective"
      ],
      [
        "oep-ke-keph-pharmacy-068-option-3",
        "Generic substitution is illegal in all circumstances"
      ]
    ],
    "answer": "oep-ke-keph-pharmacy-068-option-1",
    "explanation": "A generic medicine contains the same active pharmaceutical ingredient as the originator and must meet the same quality, safety and bioequivalence standards required for registration. Quality-assured generics expand access to affordable essential medicines.",
    "rationales": {
      "oep-ke-keph-pharmacy-068-option-0": "A generic has the same active ingredient, not a different one.",
      "oep-ke-keph-pharmacy-068-option-2": "A bioequivalent, quality-assured generic is not less effective than the originator.",
      "oep-ke-keph-pharmacy-068-option-3": "Generic substitution is permitted under appropriate professional and regulatory conditions."
    },
    "source": "OpenExamPrep",
